cd /app && cat > src/onboarding/entities/attributionDirectory.entity.ts <<'EOF'
import { Logger } from '@nestjs/common';
import { getDocument } from '../../utils/aws/s3.js';
import { getParameterValue } from '../../utils/aws/awsSSM.js';
import { getAllInstancesInRegion } from '../../utils/aws/awsEc2.js';
import { MeteredAccount } from './meteringAccounts.entity.js';

const POOL_REFERENCE = 'pool/';
const UNIT_REFERENCE = 'unit/';
const ALIAS_REFERENCE = 'alias/';
const NODE_REFERENCE = 'node/';

const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';
const NODE_CHARGE_CODE_TAG = 'paigoChargeCode';
const NODE_PASS_THROUGH_TAG = 'paigoRollsInto';

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /**
     * Where this pool hands its spend on to, when the pool does not keep it.
     * @example "unit/ember"
     */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * A business unit, kept one object per unit so a single unit can be rewritten
 * without touching the rest.
 */
export class AttributionUnitDocument {
    public unitId: string;
    /** The code spend stopping at this unit is booked to. */
    public chargeCode: string;
    /**
     * Where this unit hands its spend on to, when the unit does not keep it.
     * @example "alias/zircon"
     */
    public parentRef?: string;
}

/**
 * One owner along an attribution chain: the code it books spend to, and where
 * it passes the spend on to when it does not keep it.
 */
export class AttributionOwner {
    public chargeCode?: string;
    public passesTo?: string;
}

/**
 * The attribution material a business keeps beside its onboarding record.
 *
 * A reference names an owner of spend and can be any of
 * - `pool/<name>` in the pools document beside the onboarding record,
 * - `unit/<name>` as its own object under the same prefix,
 * - `alias/<name>` as a parameter the business maintains, or
 * - `node/<accountId>/<region>/<instanceId>` as tags on the instance itself.
 *
 * Any owner may pass its spend on to another owner, so a reference is the head
 * of a chain rather than an answer on its own.
 */
export class AttributionDirectory {
    private static readonly logger = new Logger(AttributionDirectory.name);

    private readonly pools: Record<string, AttributionPool>;

    private readonly bucket: string;

    private readonly prefix: string;

    private readonly accounts: Record<string, MeteredAccount>;

    private readonly credentialsFor: (account: MeteredAccount) => unknown;

    private readonly units = new Map<string, Promise<AttributionUnitDocument>>();

    private readonly aliases = new Map<string, Promise<string>>();

    private readonly nodes = new Map<string, Promise<Record<string, Record<string, string>>>>();

    private readonly resolved = new Map<string, Promise<string>>();

    private constructor({
        pools,
        bucket,
        prefix,
        accounts,
        credentialsFor,
    }: {
        pools: Record<string, AttributionPool>;
        bucket: string;
        prefix: string;
        accounts: Array<MeteredAccount>;
        credentialsFor: (account: MeteredAccount) => unknown;
    }) {
        this.pools = pools;
        this.bucket = bucket;
        this.prefix = prefix;
        this.credentialsFor = credentialsFor;
        this.accounts = {};
        (accounts ?? []).forEach((account) => {
            this.accounts[account.accountId] = account;
        });
    }

    static async load(
        bucket: string,
        prefix: string,
        {
            accounts = [],
            credentialsFor = () => undefined,
        }: { accounts?: Array<MeteredAccount>; credentialsFor?: (account: MeteredAccount) => unknown } = {},
    ): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory({ pools: document?.pools ?? {}, bucket, prefix, accounts, credentialsFor });
    }

    /**
     * The code that ends up carrying the spend a usage line starts on. The
     * reference the line carries is followed through every owner that passes
     * the cost on, so the answer is the owner that keeps it rather than the one
     * the line names.
     *
     * When a chain closes on itself the owners in the cycle are all standing in
     * for one another, so the code the cycle shares is the one that carries it.
     * When a chain runs into material the business has not written yet, the
     * last owner we could read keeps the spend.
     */
    chargeCodeFor(reference: string): Promise<string> {
        if (!reference) {
            return Promise.resolve(undefined);
        }
        if (!this.resolved.has(reference)) {
            this.resolved.set(reference, this.followChain(reference));
        }
        return this.resolved.get(reference);
    }

    private async followChain(reference: string): Promise<string> {
        const walked: Array<AttributionOwner & { reference: string }> = [];
        const positions = new Map<string, number>();
        let current = reference;

        while (current) {
            if (positions.has(current)) {
                return AttributionDirectory.codeSharedByCycle(walked.slice(positions.get(current)));
            }
            // Each owner names the next one, so the chain has to be read in order
            // eslint-disable-next-line no-await-in-loop
            const owner = await this.ownerFor(current);
            if (!owner) {
                AttributionDirectory.logger.warn(`Attribution reference ${current} has no owner, keeping spend behind it`);
                return AttributionDirectory.lastCodeWalked(walked);
            }
            positions.set(current, walked.length);
            walked.push({ ...owner, reference: current });
            if (!owner.passesTo) {
                return owner.chargeCode ?? AttributionDirectory.lastCodeWalked(walked);
            }
            current = owner.passesTo;
        }
        return undefined;
    }

    /**
     * The code a cycle of owners shares. They all hand the spend to one
     * another, so whichever code they agree on is the one that carries it.
     */
    private static codeSharedByCycle(cycle: Array<AttributionOwner>): string {
        const counts = new Map<string, number>();
        cycle.forEach(({ chargeCode }) => {
            if (chargeCode) {
                counts.set(chargeCode, (counts.get(chargeCode) ?? 0) + 1);
            }
        });
        let shared: string;
        let best = 0;
        counts.forEach((count, code) => {
            if (count > best) {
                best = count;
                shared = code;
            }
        });
        return shared;
    }

    /** The last owner along a chain that named a code of its own. */
    private static lastCodeWalked(walked: Array<AttributionOwner>): string {
        for (let index = walked.length - 1; index >= 0; index -= 1) {
            if (walked[index].chargeCode) {
                return walked[index].chargeCode;
            }
        }
        return undefined;
    }

    private async ownerFor(reference: string): Promise<AttributionOwner> {
        if (reference.startsWith(POOL_REFERENCE)) {
            const pool = this.pools[reference.slice(POOL_REFERENCE.length)];
            return pool ? { chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo } : undefined;
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            const unit = await this.unit(reference.slice(UNIT_REFERENCE.length));
            return unit ? { chargeCode: unit.chargeCode, passesTo: unit.parentRef } : undefined;
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            const target = await this.alias(reference.slice(ALIAS_REFERENCE.length));
            // An alias only ever points at another owner, it never keeps spend
            return target ? { passesTo: target } : undefined;
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return this.node(reference.slice(NODE_REFERENCE.length));
        }
        return undefined;
    }

    private unit(name: string): Promise<AttributionUnitDocument> {
        if (!this.units.has(name)) {
            this.units.set(
                name,
                getDocument<AttributionUnitDocument>(this.bucket, `${this.prefix}units/${name}.json`).catch(() => undefined),
            );
        }
        return this.units.get(name);
    }

    private alias(name: string): Promise<string> {
        if (!this.aliases.has(name)) {
            this.aliases.set(name, getParameterValue(`${ALIAS_PARAMETER_PREFIX}${name}`));
        }
        return this.aliases.get(name);
    }

    private async node(locator: string): Promise<AttributionOwner> {
        const [accountId, region, instanceId] = locator.split('/');
        if (!accountId || !region || !instanceId) {
            return undefined;
        }
        const tagsByInstance = await this.instanceTags(accountId, region);
        const tags = tagsByInstance[instanceId];
        if (!tags) {
            return undefined;
        }
        return { chargeCode: tags[NODE_CHARGE_CODE_TAG], passesTo: tags[NODE_PASS_THROUGH_TAG] };
    }

    private instanceTags(accountId: string, region: string): Promise<Record<string, Record<string, string>>> {
        const location = `${accountId}/${region}`;
        if (!this.nodes.has(location)) {
            const account = this.accounts[accountId];
            this.nodes.set(
                location,
                account
                    ? getAllInstancesInRegion(region, this.credentialsFor(account))
                          .then((instances) => {
                              const tagsByInstance: Record<string, Record<string, string>> = {};
                              instances.forEach(({ InstanceId, Tags }) => {
                                  const tags: Record<string, string> = {};
                                  (Tags ?? []).forEach(({ Key, Value }) => {
                                      tags[Key] = Value;
                                  });
                                  tagsByInstance[InstanceId] = tags;
                              });
                              return tagsByInstance;
                          })
                          .catch((error) => {
                              AttributionDirectory.logger.warn(
                                  `Could not read instances in ${location}: ${error?.message ?? error}`,
                              );
                              return {};
                          })
                    : Promise.resolve({}),
            );
        }
        return this.nodes.get(location);
    }
}
EOF
